268	                    "SELECT (SELECT COUNT(*) FROM PUBLIC.person WHERE sheet_id = ? AND LOWER(name) = LOWER(?) AND id <> ?)"
269	                            + " + (SELECT COUNT(*) FROM PUBLIC.person_alias WHERE sheet_id = ? AND LOWER(alias) = LOWER(?)"
