    /** Copy a person onto another sheet, as added there on its today: their name, the grade they were first given,
     *  every grade they were given (with its from-date), their terms, contact and aliases (in the order they were
     *  added), and the sheet they came from (their statements are joined by the caller); the new person's id. Their claims are moved by the caller. */
    public long transferIn(String fromSheet, long id, String toSheet) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(c -> {
            PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on, list_position, origin_sheet, arrived_on)"
                            + " SELECT ?, p.name, p.grade, p.terms, p.contact, (SELECT s.today FROM sheet s WHERE s.id = ?),"
                            + " (SELECT COALESCE(MAX(q.list_position), 0) + 1 FROM person q WHERE q.sheet_id = ?), ?,"
                            + " (SELECT s.today FROM sheet s WHERE s.id = ?)"
                            + " FROM person p WHERE p.id = ? AND p.sheet_id = ?", new String[] { "id" });
            ps.setString(1, toSheet);
            ps.setString(2, toSheet);
            ps.setString(3, toSheet);
            ps.setString(4, fromSheet);
            ps.setString(5, toSheet);
            ps.setLong(6, id);
            ps.setString(7, fromSheet);
            return ps;
        }, keys);
        long arrived = keys.getKey().longValue();
        tags(toSheet, arrived, jdbc.queryForObject("SELECT tags FROM person WHERE id = ? AND sheet_id = ?", String.class, id, fromSheet));
        for (GradeFrom g : grades(fromSheet, id)) {
            grade(toSheet, arrived, g.grade(), g.from() == null ? null : LocalDate.parse(g.from()));
        }
        jdbc.update("INSERT INTO person_terms (sheet_id, person_id, terms, from_date) SELECT ?, ?, terms, from_date"
                + " FROM person_terms WHERE sheet_id = ? AND person_id = ? ORDER BY from_date", toSheet, arrived, fromSheet, id);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, alias FROM person_alias"
                + " WHERE sheet_id = ? AND person_id = ? ORDER BY id", toSheet, arrived, fromSheet, id);
        return arrived;
    }

    /** Join one person's statements to another's (possibly on another sheet), as a merge or transfer does: the
     *  receiving person's statement count becomes their own plus the other's, the other's statements coming before
     *  theirs, so their last statement stays theirs (or, having none, becomes the other's). */
    public void joinStatements(String fromSheet, long fromId, String toSheet, long intoId) {
        Map<String, Object> from = jdbc.queryForMap("SELECT statement_count, stated_total, statement_date FROM person"
                + " WHERE id = ? AND sheet_id = ?", fromId, fromSheet);
        long count = ((Number) from.get("statement_count")).longValue();
        if (count <= 0) return;
        // Shift the receiving person's statements after the other's (through negatives, keeping seq unique).
        jdbc.update("UPDATE person_statement SET seq = -(seq + ?) WHERE sheet_id = ? AND person_id = ?", count, toSheet, intoId);
        jdbc.update("UPDATE person_statement SET seq = -seq WHERE sheet_id = ? AND person_id = ? AND seq < 0", toSheet, intoId);
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, due_total, statement_date)"
                + " SELECT ?, ?, seq, due_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ?",
                toSheet, intoId, fromSheet, fromId);
        jdbc.update("UPDATE person SET stated_total = CASE WHEN statement_count = 0 THEN ? ELSE stated_total END,"
                + " statement_date = CASE WHEN statement_count = 0 THEN ? ELSE statement_date END,"
                + " statement_count = statement_count + ? WHERE id = ? AND sheet_id = ?",
                from.get("stated_total"), from.get("statement_date"), count, intoId, toSheet);
    }

    /** Add names (in order) to a person's aliases, as a merge joins the merged person's name and aliases. */
    public void joinAliases(String sheetId, long id, List<String> names) {
        for (String name : names) {
            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, id, name);
        }
    }

    /** Take a person off the sheet entirely: their patron links (both ways), pool and crew memberships, closed periods'
     *  figures, watchers, holds, past retirements, snapshots, statements, grades, aliases and plans go with them. Their claims must already be gone. */
    public void remove(String sheetId, long id) {
        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM period_pool_cut WHERE sheet_id = ? AND member_key = ?", sheetId, String.valueOf(id));
        jdbc.update("DELETE FROM period_opening WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM plan_claim WHERE sheet_id = ? AND plan_id IN (SELECT id FROM plan WHERE sheet_id = ? AND person_id = ?)",
                sheetId, sheetId, id);
        jdbc.update("DELETE FROM plan_change WHERE sheet_id = ? AND plan_id IN (SELECT id FROM plan WHERE sheet_id = ? AND person_id = ?)",
                sheetId, sheetId, id);
        jdbc.update("DELETE FROM plan_pause WHERE sheet_id = ? AND plan_id IN (SELECT id FROM plan WHERE sheet_id = ? AND person_id = ?)",
                sheetId, sheetId, id);
        jdbc.update("DELETE FROM plan WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        jdbc.update("DELETE FROM person WHERE id = ? AND sheet_id = ?", id, sheetId);
    }

    /** Merge one person into another: the merged name and aliases become the other's aliases (name first); the
     *  merged person's patrons are added to the other's (not themselves, no repeats), anyone naming the merged
     *  person names the other instead (no repeats); pool memberships move to the other (shares added, at most
     *  100.00, when the other is already a member), as do crew leads and crew memberships (no repeats); closed periods' figures are added to the other's. Their
     *  statements are joined to the other's (see {@link #joinStatements}); their holds, past retirements, snapshots, grades, watchers and contact go with them, their plans move to the other, and the merged person leaves the sheet.
     *  Their claims must already have been moved. */
    public void merge(String sheetId, long fromId, long intoId) {
        String name = jdbc.queryForObject("SELECT name FROM person WHERE id = ? AND sheet_id = ?", String.class, fromId, sheetId);
        List<String> aliases = jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                String.class, sheetId, fromId);
        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, intoId, name);
        for (String alias : aliases) {
            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, intoId, alias);
        }

        // The merged person's patrons become the other's.
        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id) SELECT sheet_id, ?, patron_id FROM patron p"
                + " WHERE p.sheet_id = ? AND p.person_id = ? AND p.patron_id <> ? AND NOT EXISTS (SELECT 1 FROM patron q"
                + " WHERE q.person_id = ? AND q.patron_id = p.patron_id) ORDER BY p.seq", intoId, sheetId, fromId, intoId, intoId);
        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        // Anyone naming the merged person names the other instead.
        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id, seq) SELECT sheet_id, person_id, ?, seq FROM patron p"
                + " WHERE p.sheet_id = ? AND p.patron_id = ? AND p.person_id <> ? AND NOT EXISTS (SELECT 1 FROM patron q"
                + " WHERE q.person_id = p.person_id AND q.patron_id = ?)", intoId, sheetId, fromId, intoId, intoId);
        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND patron_id = ?", sheetId, fromId);

        // Pool memberships move; shares are added where the other is already a member.
        jdbc.update("UPDATE pool_member m SET share = LEAST(100.00, share + (SELECT f.share FROM pool_member f"
                + " WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?))"
                + " WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member f"
                + " WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?)",
                fromId, sheetId, intoId, fromId);
        jdbc.update("DELETE FROM pool_member m WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM"
                + " pool_member o WHERE o.sheet_id = m.sheet_id AND o.pool_name = m.pool_name AND o.person_id = ?)",
                sheetId, fromId, intoId);
        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);

        // Crews follow too: a crew the merged person leads is led by the other (who leaves its members), and their
        // crew memberships move to the other where the other is not already in that crew.
        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", intoId, sheetId, fromId);
        jdbc.update("DELETE FROM crew_member m WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM crew c"
                + " WHERE c.sheet_id = m.sheet_id AND c.name = m.crew_name AND c.lead_id = ?)", sheetId, intoId, intoId);
        jdbc.update("DELETE FROM crew_member m WHERE m.sheet_id = ? AND m.person_id = ? AND (EXISTS (SELECT 1 FROM"
                + " crew_member o WHERE o.sheet_id = m.sheet_id AND o.crew_name = m.crew_name AND o.person_id = ?)"
                + " OR EXISTS (SELECT 1 FROM crew c WHERE c.sheet_id = m.sheet_id AND c.name = m.crew_name AND c.lead_id = ?))",
                sheetId, fromId, intoId, intoId);
        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);

        // A closed period's figure follows the claims.
        jdbc.update("UPDATE period_person_total t SET total = total + (SELECT f.total FROM period_person_total f"
                + " WHERE f.period_id = t.period_id AND f.person_id = ?), carried = carried + (SELECT f.carried FROM"
                + " period_person_total f WHERE f.period_id = t.period_id AND f.person_id = ?) WHERE t.sheet_id = ? AND t.person_id = ?"
                + " AND EXISTS (SELECT 1 FROM period_person_total f WHERE f.period_id = t.period_id AND f.person_id = ?)",
                fromId, fromId, sheetId, intoId, fromId);
        jdbc.update("DELETE FROM period_person_total t WHERE t.sheet_id = ? AND t.person_id = ? AND EXISTS (SELECT 1"
                + " FROM period_person_total o WHERE o.period_id = t.period_id AND o.person_id = ?)", sheetId, fromId, intoId);
        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
        // So do the opening balances.
        jdbc.update("UPDATE period_opening t SET amount = amount + (SELECT f.amount FROM period_opening f"
                + " WHERE f.period_id = t.period_id AND f.person_id = ?) WHERE t.sheet_id = ? AND t.person_id = ?"
                + " AND EXISTS (SELECT 1 FROM period_opening f WHERE f.period_id = t.period_id AND f.person_id = ?)",
                fromId, sheetId, intoId, fromId);
        jdbc.update("DELETE FROM period_opening t WHERE t.sheet_id = ? AND t.person_id = ? AND EXISTS (SELECT 1"
                + " FROM period_opening o WHERE o.period_id = t.period_id AND o.person_id = ?)", sheetId, fromId, intoId);
        jdbc.update("UPDATE period_opening SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);

        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        joinStatements(sheetId, fromId, sheetId, intoId);
        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
        // Plans follow the claims.
        jdbc.update("UPDATE plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
        jdbc.update("DELETE FROM person WHERE id = ? AND sheet_id = ?", fromId, sheetId);
    }
}

